import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
const pkg = resolve(process.argv[2]);
const api = await import(pathToFileURL(resolve(pkg, 'simple_ffi_web.js')));
await api.default({module_or_path: await readFile(resolve(pkg, 'simple_ffi_web_bg.wasm'))});
assert.equal(api.standaloneAdd(20, 22), 42);
assert.equal(await api.standaloneAsync('async works'), 'async works');
assert.equal(api.standaloneCustom(' PERSON@Example.COM '), 'person@example.com');
assert.throws(() => api.standaloneFailure(), e => e.details.tag === 'InvalidInput');
assert.equal(api.wasmOnly(), 'wasm');
assert.equal(api.nativeOnly, undefined);
assert.deepEqual(api.conditionalRecord({common: 'shared', browser: true}), {common: 'shared', browser: true});
const release = process.argv.includes('--release');
assert.equal(typeof api.releaseOnly, release ? 'function' : 'undefined');
assert.equal(typeof api.debugOnly, release ? 'undefined' : 'function');
assert.equal(typeof api.featureOnly, process.argv.includes('--feature') ? 'function' : 'undefined');
const types = await readFile(resolve(pkg, 'simple_ffi_web.d.ts'), 'utf8');
assert.match(types, /export function standaloneAdd\(left: number, right: number\): number/);
assert.match(types, /standaloneAsync\(value: string\): Promise<string>/);
assert.match(types, /standaloneProfile\(value: WebProfile\): WebProfile/);
assert.doesNotMatch(types, /nativeOnly|desktop:/);
assert.equal(types.includes('featureOnly('), process.argv.includes('--feature'));
assert.equal(types.includes('releaseOnly('), release);
assert.equal(types.includes('debugOnly('), !release);
console.log('Standalone functions and conditional WASM APIs passed');
